H,W=27,23
g=[[8]*W for _ in range(H)]
frames=[(1,1,2),(7,1,4),(13,1,3),(19,1,1)] # top row, left col, color; zero-based
counts={2:2,4:4,3:1,1:1}
for top,left,col in frames:
    for r in range(top,top+5):
        for c in range(left,left+11):
            if r in (top,top+4) or c in (left,left+10): g[r][c]=col
    n=counts[col]
    row=top+2
    rels=list(range(8-2*(n-1),9,2))
    for rel in rels: g[row][left+rel-1]=col
print('\n'.join(' '.join(map(str,row)) for row in g))

